-- The ladders of client pair 50 (server/README.md "Pair 50 items"): using one moves the player one floor up, the way the
-- base's ladders do (the base registers them with other/teleport.lua by item id and an id list inside that script; ours are
-- registered here, from data/lib/chaos_pair50_items.lua, generated by server/tools/install_pair50_items.py --lua). The
-- destination is Position:moveUpstairs() of the base lib; a player with a protection zone lock may not enter a protection
-- zone that way. The items exist after the install step "pair50items" and need a client on pair 50 or newer. The stairs
-- and holes of the pair need no script: they carry the floorchange attribute in items.xml.
if not ChaosPair50 then
	dofile("data/lib/chaos_pair50_items.lua")
end

local ladder = Action()

function ladder.onUse(player, item, fromPosition, target, toPosition, isHotkey)
	local destination = Position(fromPosition)
	destination:moveUpstairs()
	if player:isPzLocked() and Tile(destination):hasFlag(TILESTATE_PROTECTIONZONE) then
		player:sendCancelMessage(RETURNVALUE_PLAYERISPZLOCKED)
		return true
	end
	player:teleportTo(destination, false)
	return true
end

local n = 0
for _, id in ipairs(ChaosPair50.ladders) do
	if ItemType(id):getId() ~= 0 then
		ladder:id(id)
		n = n + 1
	end
end
if n > 0 then
	ladder:register()
end
